38	function run(command: string, args: string[], input?: string): string {
39	  const result = spawnSync(command, args, {
40	    cwd: process.cwd(),
41	    encoding: "utf8",
42	    input,
43	  });
44	  if (result.status !== 0) {
45	    const detail = (result.stderr || result.stdout || "unknown error").trim();
46	    throw new Error(`${command} ${args.join(" ")} failed: ${detail}`);
47	  }
48	  return result.stdout.trim();
49	}
