51	function jsonCommand<T>(command: string, args: string[], input?: string): T {
52	  const output = run(command, args, input);
53	  try {
54	    return JSON.parse(output) as T;
55	  } catch {
56	    throw new Error(`${command} returned invalid JSON`);
57	  }
58	}
