60	function ghApi<T>(endpoint: string, method = "GET", payload?: unknown): T {
61	  const args = ["api"];
62	  let input: string | undefined;
63	  if (method !== "GET") args.push("-X", method);
64	  args.push(endpoint);
65	  if (payload !== undefined) {
66	    args.push("--input", "-");
67	    input = JSON.stringify(payload);
68	  }
69	  return jsonCommand<T>("gh", args, input);
70	}
