72	function ghApiPages<T>(endpoint: string): T[] {
73	  const pages = jsonCommand<T[][]>("gh", [
74	    "api",
75	    endpoint,
76	    "--paginate",
77	    "--slurp",
78	  ]);
79	  return pages.flat();
80	}
