82	function parseOptions(argv: string[]): Options {
83	  const options: Options = {
84	    artifactUrl: process.env.ARTIFACT?.trim() || undefined,
85	    open: ["1", "true", "yes"].includes((process.env.OPEN ?? "").toLowerCase()),
86	  };
87	  for (let index = 0; index < argv.length; index += 1) {
88	    const argument = argv[index];
