110	export function githubRepoFromRemote(remote: string): string {
111	  const normalized = remote
112	    .trim()
113	    .replace(/^git@github\.com:/, "")
114	    .replace(/^ssh:\/\/git@github\.com\//, "")
115	    .replace(/^https:\/\/github\.com\//, "")
116	    .replace(/\.git$/, "");
117	  if (!/^[^/]+\/[^/]+$/.test(normalized)) {
118	    throw new Error(`unsupported GitHub remote: ${remote}`);
119	  }
120	  return normalized;
121	}
