export default async (ctx, client) => {
  const CHROME = 432;
  const paths = JSON.parse(process.env.SHOT_PATHS || "[]");
  const out = [];
  const nav = await client.operations.execute({
    connection_id: CHROME,
    operation_key: "navigate",
    input: { url: "http://localhost:5173/", open_in_new_tab: true, wait_for_load: true },
  });
  const tab = nav.output.tab_id;
  for (const p of paths) {
    await client.operations.execute({
      connection_id: CHROME,
      operation_key: "navigate",
      input: { tab_id: tab, url: "http://localhost:5173" + p, wait_for_load: true },
    });
    await client.operations.execute({
      connection_id: CHROME,
      operation_key: "evaluate",
      input: { tab_id: tab, expression: "(async()=>{await new Promise(r=>setTimeout(r,3500));return {url:location.href,title:document.title,text:document.body.innerText.slice(0,400)}})()", await_promise: true },
    });
    const shot = await client.operations.execute({
      connection_id: CHROME,
      operation_key: "screenshot",
      input: { tab_id: tab },
    });
    out.push({ path: p, output: shot.output });
  }
  await client.operations.execute({ connection_id: CHROME, operation_key: "close_tab", input: { tab_id: tab } });
  return out;
};

