D = pathlib.Path(__file__).parent
OUT = D / "ui-proof-2501.html"

PAIRS = [
    (
        "buremba_agents",
        "/$owner/agents",
        "Agents is a destination, not a sidebar roster",
        "Before, the only thing at this path was a bare <em>Build a managed agent</em> form, and the "
        "workspace's agents lived as a cramped <span class='k'>AGENTS</span> list in the sidebar. After, the "
        "route is a real page: <em>All / Managed / Connected</em> filters, a <em>Copy prompt</em> button that "
        "hands the user the onboarding prompt for an external agent, and <em>Build a managed agent</em> demoted "
        "to a corner action. Managed agents carry the Lobu mark; connected apps carry their own.",
    ),
    (
        "buremba_connectors",
        "/$owner/connectors",
        "Connectors keeps the setup offers; the Agents facet leaves",
        "The sidebar reorders to Activity → Connectors → Agents → Behaviors → Memory, and the per-agent roster "
        "is gone from it entirely. On the connectors page itself the <span class='k'>Agents</span> facet chip "
        "disappears — agents are no longer a way to slice connectors — while Owletto for Mac, the Chrome "
        "extension and the CLI stay here as setup offers.",
    ),
    (
        "buremba_behaviors",
        "/$owner/behaviors",
        "Behaviors moves below Agents and keeps working",
        "Behaviors is unchanged in substance; this pair is the regression check that reordering the nav and "
        "deleting the agent roster did not disturb the workspace-level Behaviors page it now sits under.",
    ),
]


def embed(name: str) -> str:
    raw = (D / f"jpg_{name}.jpg").read_bytes()
    return "data:image/jpeg;base64," + base64.b64encode(raw).decode()


def figure(side: str, name: str) -> str:
    label = "Before" if side == "before" else "After"
    sha = "f0a99d09" if side == "before" else "2741388c"
    return f"""        <figure class="shot {side}">
          <figcaption><span class="tag">{label}</span><code>{sha}</code></figcaption>
          <img src="{embed(f'{side}_{name}')}" alt="{label}: {name.replace('_', ' ')}" loading="lazy" />
        </figure>"""


sections = []
for index, (name, route, title, note) in enumerate(PAIRS, start=1):
    sections.append(
